#include <vector>
#include <map>
#include <string>

class Solution {
public:
    int countArrays(std::vector<int>& digit_sums, int max_val = 50) {
        const int MOD = 1e9 + 7;
        auto getDigitSum = [](int x) {
            int s = 0;
            while (x > 0) { s += x % 10; x /= 10; }
            return s;
        };
        std::vector<std::vector<int>> candidates;
        for (int target : digit_sums) {
            std::vector<int> valid;
            for (int x = 0; x <= max_val; ++x) {
                if (getDigitSum(x) == target) valid.push_back(x);
            }
            candidates.push_back(valid);
        }
        if (candidates[0].empty()) return 0;
        std::map<int, int> dp;
        for (int x : candidates[0]) dp[x] = 1;
        for (size_t i = 1; i < candidates.size(); ++i) {
            std::map<int, int> next_dp;
            for (int y : candidates[i]) {
                long long sum = 0;
                for (const auto& [x, count] : dp) {
                    if (x <= y) sum = (sum + count) % MOD;
                }
                next_dp[y] = sum;
            }
            dp = std::move(next_dp);
        }
        long long total = 0;
        for (const auto& [k, v] : dp) total = (total + v) % MOD;
        return total;
    }
};

import java.util.*;

class Solution {
    public int countArrays(int[] digitSums, int maxVal) {
        int MOD = 1_000_000_007;
        List<List<Integer>> candidates = new ArrayList<>();
        for (int target : digitSums) {
            List<Integer> valid = new ArrayList<>();
            for (int x = 0; x <= maxVal; x++) {
                int s = 0, tmp = x;
                while (tmp > 0) { s += tmp % 10; tmp /= 10; }
                if (s == target) valid.add(x);
            }
            candidates.add(valid);
        }
        if (candidates.get(0).isEmpty()) return 0;
        Map<Integer, Integer> dp = new TreeMap<>();
        for (int x : candidates.get(0)) dp.put(x, 1);
        for (int i = 1; i < candidates.size(); i++) {
            Map<Integer, Integer> nextDp = new TreeMap<>();
            for (int y : candidates.get(i)) {
                long sum = 0;
                for (var entry : dp.entrySet()) {
                    if (entry.getKey() <= y) sum = (sum + entry.getValue()) % MOD;
                }
                nextDp.put(y, (int) sum);
            }
            dp = nextDp;
        }
        long total = 0;
        for (int v : dp.values()) total = (total + v) % MOD;
        return (int) total;
    }
}

