            if (s === target) valid.push(x);
        }
        candidates.push(valid);
    }
    if (candidates[0].length === 0) return 0;
    let dp = new Map();
    for (const x of candidates[0]) dp.set(x, 1);
    for (let i = 1; i < candidates.length; i++) {
        const nextDp = new Map();
        for (const y of candidates[i]) {
            let sum = 0;
            for (const [x, count] of dp.entries()) {
                if (x <= y) sum = (sum + count) % MOD;
            }
            nextDp.set(y, sum);
        }
        dp = nextDp;
    }
    let total = 0;
    for (const v of dp.values()) total = (total + v) % MOD;
    return total;
}
